#[derive(Debug, Clone)]
struct FormState {
    id: Option<i64>,
    name: String,
    kind: String,
    endpoint: String,
    priority: i64,
    enabled: bool,
    note: String,
}

impl Default for FormState {
    fn default() -> Self {
        Self {
            id: None,
            name: String::new(),
            kind: "实时行情".to_string(),
            endpoint: String::new(),
            priority: 3,
            enabled: true,
            note: String::new(),
        }
    }
}

impl FormState {
    fn from_source(s: &DataSource) -> Self {
        Self {
            id: Some(s.id),
            name: s.name.clone(),
            kind: s.kind.clone(),
            endpoint: s.endpoint.clone(),
            priority: s.priority,
            enabled: s.enabled,
            note: s.note.clone(),
        }
    }

    fn to_input(&self) -> DataSourceInput {
        let note = self.note.trim();
        DataSourceInput {
            name: self.name.trim().to_string(),
            kind: self.kind.trim().to_string(),
            endpoint: self.endpoint.trim().to_string(),
            priority: self.priority,
            enabled: self.enabled,
            note: if note.is_empty() { None } else { Some(note.to_string()) },
        }
    }

    fn validate(&self) -> Result<(), String> {
        if self.name.trim().is_empty() { return Err("名称不能为空".into()); }
        if self.kind.trim().is_empty() { return Err("类型不能为空".into()); }
        if self.endpoint.trim().is_empty() { return Err("接口地址不能为空".into()); }
        if !(1..=5).contains(&self.priority) { return Err("优先级应在 1~5 之间".into()); }
        Ok(())
    }
}

