fn probe_endpoint(endpoint: &str) -> ProbeResult {
    let ep = endpoint.trim();
    if ep.is_empty() {
        return ProbeResult::Fail;
    }
    if ep.starts_with("file://") {
        return ProbeResult::Unsupported;
    }
