/// 取 `~/.make-stock-money/app.db`,确保目录存在
pub fn db_path() -> PathBuf {
    let home = dirs::home_dir().expect("无法获取用户主目录");
    let dir = home.join(".make-stock-money");
    if !dir.exists() {
        std::fs::create_dir_all(&dir).expect("创建 ~/.make-stock-money 目录失败");
    }
    dir.join("app.db")
}

/// 初始化连接 + 建表 + 首次启动预置默认数据
pub fn init() -> Mutex<Connection> {
    let path = db_path();
    let conn = Connection::open(&path).expect("打开 SQLite 失败");
    conn.execute_batch(
        r#"
        CREATE TABLE IF NOT EXISTS data_sources (
            id          INTEGER PRIMARY KEY AUTOINCREMENT,
            name        TEXT    NOT NULL,
            kind        TEXT    NOT NULL,
            endpoint    TEXT    NOT NULL,
            priority    INTEGER NOT NULL DEFAULT 3,
            latency_ms  INTEGER NOT NULL DEFAULT 0,
            enabled     INTEGER NOT NULL DEFAULT 1,
            status      TEXT    NOT NULL DEFAULT 'online',
            note        TEXT    NOT NULL DEFAULT '',
            created_at  TEXT    NOT NULL,
            updated_at  TEXT    NOT NULL
        );
        "#,
    )
    .expect("建表失败");

    // 表空时插入默认数据
    let count: i64 = conn
        .query_row("SELECT COUNT(*) FROM data_sources", [], |r| r.get(0))
        .unwrap_or(0);
    if count == 0 {
        seed_defaults(&conn);
    }

    Mutex::new(conn)
}

fn seed_defaults(conn: &Connection) {
    let now = chrono::Local::now().to_rfc3339();
    let defaults = [
        ("新浪财经",   "实时行情",   "https://hq.sinajs.cn",           1, true,  "online", "", 48),
        ("东方财富",   "实时行情",   "https://push2.eastmoney.com",    2, true,  "online", "", 62),
        ("通达信本地", "本地行情",   "127.0.0.1:7721",                  3, true,  "online", "", 12),
        ("Tushare Pro","财务/基本面","https://api.tushare.pro",         4, false, "warning","需配置 token", 215),
        ("AkShare 聚合","新闻/公告", "https://akshare.akfamily.xyz",    5, true,  "warning","", 380),
        ("Wind 导入",  "历史数据",   "file://D:/data/wind/",            5, false, "offline","本地文件夹", 0),
    ];
    let mut stmt = conn
        .prepare(
            "INSERT INTO data_sources
             (name, kind, endpoint, priority, enabled, status, note, latency_ms, created_at, updated_at)
             VALUES (?1, ?2, ?3, ?4, ?5, ?6, ?7, ?8, ?9, ?9)",
        )
        .expect("准备 INSERT 失败");
    for d in defaults {
        stmt.execute(params![d.0, d.1, d.2, d.3, d.4 as i64, d.5, d.6, d.7, now])
            .expect("插入默认数据失败");
    }
}

