use rusqlite::{params, Connection};
use serde::{Deserialize, Serialize};

/// 数据源表里的一条记录 —— 完整字段,前端不一定要全部展示
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct DataSource {
    pub id: i64,
    pub name: String,
    pub kind: String,       // 实时行情 / 财务 / 新闻 / 本地行情 / 历史数据 ...
    pub endpoint: String,   // URL 或 host:port 或 file://
    pub priority: i64,      // 1~5
    pub latency_ms: i64,    // 最近一次测试延迟
    pub enabled: bool,      // 是否启用
    pub status: String,     // online / warning / offline
    pub note: String,       // 备注
    pub created_at: String, // ISO8601
    pub updated_at: String, // ISO8601
}

/// 前端创建/更新时用的载荷(id 由 SQLite 自动生成)
#[derive(Debug, Clone, Deserialize)]
pub struct DataSourceInput {
