/* ---------- 数据源页:头部 + 操作区 ---------- */
.page-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 0.8rem;
  margin-bottom: 1.2rem;
}

.page-header .page-title {
  margin: 0;
}

.header-actions {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  flex-wrap: wrap;
}

.header-actions .search-input {
  max-width: 260px;
}

/* ---------- 顶部错误条 (与 .banner 风格类似,但用 .alert) ---------- */
.alert {
  display: flex;
