  padding: 0.55rem 0.8rem;
  border-radius: 6px;
  font-size: 0.88rem;
  margin: 0.6rem 0 1rem;
  border: 1px solid transparent;
}

.alert.error {
  background: #fdecec;
  color: #b3261e;
  border-color: #f5c2c0;
}

.alert > span {
  flex: 1;
}

@media (prefers-color-scheme: dark) {
  .alert.error {
    background: rgba(179, 38, 30, 0.2);
    color: #f5b5b1;
    border-color: rgba(179, 38, 30, 0.45);
  }
}

/* ---------- 表格通用(数据源表) ---------- */
.ds-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 0.92rem;
  border: 1px solid #e0e0e0;
  background: #ffffff;
}

.ds-table thead {
  background-color: #f4f4f5;
}

.ds-table th,
.ds-table td {
  padding: 0.55rem 0.8rem;
  text-align: left;
  border-bottom: 1px solid #ececec;
  vertical-align: middle;
}

.ds-table th.num,
.ds-table td.num {
  text-align: right;
  font-variant-numeric: tabular-nums;
}

.ds-table tbody tr:nth-child(even) {
  background-color: #fafafa;
}

.ds-table tbody tr:hover {
  background-color: #f0f6ff;
}

.ds-table .mono {
