// =========================================================================
//                       与后端 db::DataSource 对齐的镜像
// =========================================================================
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
struct DataSource {
    id: i64,
    name: String,
    kind: String,
    endpoint: String,
    priority: i64,
    latency_ms: i64,
    enabled: bool,
    status: String, // "online" / "warning" / "offline"
    note: String,
    #[serde(rename = "createdAt", alias = "created_at")]
    created_at: String,
    #[serde(rename = "updatedAt", alias = "updated_at")]
    updated_at: String,
}

#[derive(Debug, Clone, PartialEq)]
enum DsStatus {
    Online,
    Warning,
    Offline,
}

impl DsStatus {
    fn parse(s: &str) -> Self {
        match s {
            "online" => Self::Online,
            "offline" => Self::Offline,
            _ => Self::Warning,
        }
    }
    fn label(&self) -> &'static str {
        match self {
            Self::Online => "正常",
            Self::Warning => "异常",
            Self::Offline => "离线",
        }
    }
    fn badge_class(&self) -> &'static str {
        match self {
            Self::Online => "badge online",
            Self::Warning => "badge warn",
            Self::Offline => "badge offline",
        }
    }
}

// 前端表单使用的载荷,与后端 DataSourceInput 字段一一对应
#[derive(Debug, Clone, Default)]
struct DataSourceForm {
    id: Option<i64>, // Some = 编辑,None = 新建
    name: String,
    kind: String,
    endpoint: String,
    priority: i64,
    enabled: bool,
    note: String,
}

impl DataSourceForm {
    fn blank() -> Self {
        Self {
            id: None,
            name: String::new(),
            kind: "实时行情".to_string(),
            endpoint: String::new(),
            priority: 3,
            enabled: true,
            note: String::new(),
        }
    }
    fn from_source(s: &DataSource) -> Self {
        Self {
            id: Some(s.id),
            name: s.name.clone(),
            kind: s.kind.clone(),
            endpoint: s.endpoint.clone(),
            priority: s.priority,
            enabled: s.enabled,
            note: s.note.clone(),
        }
    }
    fn to_input(&self) -> serde_json::Value {
        serde_json::json!({
            "name": self.name,
            "kind": self.kind,
            "endpoint": self.endpoint,
            "priority": self.priority,
            "enabled": self.enabled,
            "note": self.note,
        })
    }
    fn validate(&self) -> Result<(), String> {
        if self.name.trim().is_empty() {
            return Err("名称不能为空".into());
        }
        if self.endpoint.trim().is_empty() {
            return Err("接入点不能为空".into());
        }
        if !(1..=5).contains(&self.priority) {
            return Err("优先级必须是 1~5 之间的整数".into());
        }
        Ok(())
    }
}

