             VALUES (?1, ?2, ?3, ?4, ?5, ?6, ?7, ?8, ?9, ?9)",
        )
        .map_err(|e| format!("准备 INSERT 失败: {e}"))?;
    for d in defaults {
        stmt.execute(params![d.0, d.1, d.2, d.3, d.4 as i64, d.5, d.6, d.7, now])
            .map_err(|e| format!("插入默认数据失败: {e}"))?;
    }
    Ok(())
}

