/// 3. 回到 async 上下文,把结果通过 State 写回共享连接
#[tauri::command]
async fn test_connection(state: State<'_, DbState>, id: i64) -> Result<DataSource, String> {
    // 1. 先读 endpoint(借可重入锁:锁内只做只读)
    let endpoint = {
        let conn = state.0.lock().map_err(|e| e.to_string())?;
        db::list(&conn)?
            .into_iter()
            .find(|d| d.id == id)
            .ok_or_else(|| format!("id={} 不存在", id))?
            .endpoint
    };

    // 2. 阻塞探测,放进独立线程
    let outcome: ProbeOutcome = tokio::task::spawn_blocking(move || {
        let start = std::time::Instant::now();
        let probe = probe_endpoint(&endpoint);
        let elapsed = start.elapsed().as_millis() as i64;
        match probe {
            ProbeResult::Ok => ProbeOutcome {
                latency_ms: elapsed.clamp(20, 1500),
                status: "online".to_string(),
            },
            ProbeResult::Slow => ProbeOutcome {
                latency_ms: elapsed.max(300),
                status: "warning".to_string(),
            },
            ProbeResult::Fail => ProbeOutcome {
                latency_ms: elapsed.max(100),
                status: "warning".to_string(),
            },
            ProbeResult::Unsupported => ProbeOutcome {
                latency_ms: 0,
                status: "offline".to_string(),
            },
        }
    })
    .await
    .map_err(|e| e.to_string())?;

    // 3. 写回共享连接
    let conn = state.0.lock().map_err(|e| e.to_string())?;
    db::update_test_result(&conn, id, outcome.latency_ms, &outcome.status)
}

