    pub priority: i64,
    pub enabled: bool,
    pub note: Option<String>,
}

/// 取 `~/.make-stock-money/app.db`,确保目录存在
pub fn db_path() -> Result<PathBuf, String> {
    let home = dirs::home_dir().ok_or("无法获取用户主目录")?;
    let dir = home.join(".make-stock-money");
    if !dir.exists() {
        std::fs::create_dir_all(&dir)
            .map_err(|e| format!("创建 ~/.make-stock-money 目录失败: {e}"))?;
    }
    Ok(dir.join("app.db"))
}

/// 初始化连接 + 建表 + 首次启动预置默认数据
pub fn init() -> Result<Mutex<Connection>, String> {
    let path = db_path()?;
    let conn = Connection::open(&path).map_err(|e| format!("打开 SQLite 失败: {e}"))?;
    conn.execute_batch(
        r#"
        CREATE TABLE IF NOT EXISTS data_sources (
            id          INTEGER PRIMARY KEY AUTOINCREMENT,
            name        TEXT    NOT NULL,
            kind        TEXT    NOT NULL,
            endpoint    TEXT    NOT NULL,
            priority    INTEGER NOT NULL DEFAULT 3,
            latency_ms  INTEGER NOT NULL DEFAULT 0,
            enabled     INTEGER NOT NULL DEFAULT 1,
            status      TEXT    NOT NULL DEFAULT 'online',
            note        TEXT    NOT NULL DEFAULT '',
            created_at  TEXT    NOT NULL,
            updated_at  TEXT    NOT NULL
        );
        "#,
    )
    .map_err(|e| format!("建表失败: {e}"))?;

    // 表空时插入默认数据
