// `pub` 是为了让 src-tauri/tests/ 下的集成测试能直接调用 db 层函数
pub mod db;

use std::sync::Mutex;
use std::time::Duration;

use tauri::{Manager, State};

use db::{DataSource, DataSourceInput};

/// 全局共享的 SQLite 连接
struct DbState(Mutex<rusqlite::Connection>);

#[tauri::command]
fn greet(name: &str) -> String {
    format!("Hello, {}! You've been greeted from Rust!", name)
}

#[tauri::command]
fn list_sources(state: State<'_, DbState>) -> Result<Vec<DataSource>, String> {
    let conn = state.0.lock().map_err(|e| e.to_string())?;
    db::list(&conn)
}

#[tauri::command]
fn create_source(
    state: State<'_, DbState>,
    input: DataSourceInput,
) -> Result<DataSource, String> {
    let conn = state.0.lock().map_err(|e| e.to_string())?;
    db::create(&conn, input)
}

#[tauri::command]
fn update_source(
    state: State<'_, DbState>,
    id: i64,
    input: DataSourceInput,
) -> Result<DataSource, String> {
    let conn = state.0.lock().map_err(|e| e.to_string())?;
    db::update(&conn, id, input)
}

#[tauri::command]
fn delete_source(state: State<'_, DbState>, id: i64) -> Result<(), String> {
    let conn = state.0.lock().map_err(|e| e.to_string())?;
    db::delete(&conn, id)
}

/// 探测结果 + 实际耗时
struct ProbeOutcome {
    latency_ms: i64,
    status: String,
}

/// "测试连接":
/// 1. 在 spawn_blocking 中做 TCP/HTTP 探测(避免阻塞 UI/future)
/// 2. 拿到延迟与状态字符串
/// 3. 回到 async 上下文,把结果通过 State 写回共享连接
#[tauri::command]
async fn test_connection(state: State<'_, DbState>, id: i64) -> Result<DataSource, String> {
    // 1. 先读 endpoint(借可重入锁:锁内只做只读)
    let endpoint = {
        let conn = state.0.lock().map_err(|e| e.to_string())?;
        db::list(&conn)?
            .into_iter()
            .find(|d| d.id == id)
            .ok_or_else(|| format!("id={} 不存在", id))?
            .endpoint
    };

    // 2. 阻塞探测,放进独立线程
    let outcome: ProbeOutcome = tokio::task::spawn_blocking(move || {
        let start = std::time::Instant::now();
        let probe = probe_endpoint(&endpoint);
        let elapsed = start.elapsed().as_millis() as i64;
        match probe {
            ProbeResult::Ok => ProbeOutcome {
                latency_ms: elapsed.clamp(20, 1500),
                status: "online".to_string(),
            },
            ProbeResult::Slow => ProbeOutcome {
                latency_ms: elapsed.max(300),
                status: "warning".to_string(),
            },
            ProbeResult::Fail => ProbeOutcome {
                latency_ms: elapsed.max(100),
                status: "warning".to_string(),
            },
            ProbeResult::Unsupported => ProbeOutcome {
                latency_ms: 0,
                status: "offline".to_string(),
            },
        }
    })
    .await
    .map_err(|e| e.to_string())?;


